#!/bin/sh
# VPN Selector for OpenWrt: installs LuCI -> Services -> VPN Regions and the
# region-aware WireGuard failover (/usr/bin/vpn-failover.sh), with automatic
# hotel Wi-Fi login and no DNS leaks.
#
# Copy to the router and run it:
#   scp -O install.sh root@192.168.1.1:/tmp/
#   ssh root@192.168.1.1 sh /tmp/install.sh [--killswitch]
#
#   --killswitch   remove LAN -> WAN forwarding, so LAN traffic can only leave
#                  through a VPN tunnel (nothing goes out while no tunnel is up)
#
# Safe to run again to update; your tunnels and settings are kept.
# This file is generated by tools/build-installer.sh from files/; edit those.
set -e

KILLSWITCH=0
for a in "$@"; do
  case "$a" in
    --killswitch) KILLSWITCH=1 ;;
    -h|--help) sed -n '2,13p' "$0"; exit 0 ;;
    *) echo "unknown option: $a" >&2; exit 1 ;;
  esac
done

# --- packages -------------------------------------------------------------
need=""
command -v curl >/dev/null || need="$need curl"
command -v wg >/dev/null || need="$need wireguard-tools"
[ -d /sys/module/wireguard ] || modinfo wireguard >/dev/null 2>&1 || need="$need kmod-wireguard"
[ -f /lib/netifd/proto/wireguard.sh ] || need="$need wireguard-tools"
[ -f /www/luci-static/resources/protocol/wireguard.js ] || need="$need luci-proto-wireguard"
command -v jsonfilter >/dev/null || need="$need jsonfilter"
if [ -n "$need" ]; then
  echo "Installing:$need"
  if command -v apk >/dev/null; then apk update && apk add $need
  else opkg update && opkg install $need; fi
fi

[ -f /usr/bin/vpn-failover.sh ] && [ ! -f /usr/bin/vpn-failover.sh.orig ] && \
  cp /usr/bin/vpn-failover.sh /usr/bin/vpn-failover.sh.orig

# --- settings -------------------------------------------------------------
# Seed the tunnel list from any existing WireGuard interfaces, with the region
# taken from the name (VPN_Canada -> Canada). The uplink is travelmate's wwan
# if there is one, otherwise wan.
if [ ! -s /etc/config/vpnregions ]; then
  old=$(sed -n 's/^VPNS="\([^"]*\)".*/\1/p' /usr/bin/vpn-failover.sh 2>/dev/null) || true
  wg=$(uci show network | sed -n "s/^network\.\([^.]*\)\.proto='wireguard'$/\1/p")
  uplink=wan; [ -n "$(uci -q get network.wwan)" ] && uplink=wwan
  touch /etc/config/vpnregions
  uci set vpnregions.main=settings
  uci set vpnregions.main.enabled='1'
  uci set vpnregions.main.region='all'
  uci set vpnregions.main.uplink="$uplink"
  uci set vpnregions.main.grace='60'
  uci set vpnregions.main.maxage='180'
  seen=" "
  for i in $old $wg; do
    case "$seen" in *" $i "*) continue;; esac
    seen="$seen$i "
    [ "$(uci -q get network.$i.proto)" = wireguard ] || continue
    s=$(uci add vpnregions tunnel)
    uci set vpnregions.$s.iface="$i"
    uci set vpnregions.$s.region="$(echo "${i#VPN_}" | tr -c 'A-Za-z0-9_\n-' _)"
    uci set vpnregions.$s.enabled='1'
  done
  uci commit vpnregions
fi

# --- firewall -------------------------------------------------------------
# Tunnels go in a zone called VPN (masquerade, MSS clamping) that the LAN may
# forward to. Imported configs are added to it from the LuCI page.
fw_changed=0
zone=""
for z in $(uci show firewall | sed -n "s/^firewall\.\([^.]*\)=zone$/\1/p"); do
  [ "$(uci -q get firewall.$z.name)" = VPN ] && zone=$z
done
if [ -z "$zone" ]; then
  zone=$(uci add firewall zone)
  uci set firewall.$zone.name='VPN'
  uci set firewall.$zone.input='REJECT'
  uci set firewall.$zone.output='ACCEPT'
  uci set firewall.$zone.forward='REJECT'
  uci set firewall.$zone.masq='1'
  uci set firewall.$zone.mtu_fix='1'
  # existing tunnels that are in no zone yet
  for i in $(uci show vpnregions | sed -n "s/^vpnregions\.[^.]*\.iface='\(.*\)'$/\1/p"); do
    uci show firewall | grep -q "\.network=.*'$i'" || uci add_list firewall.$zone.network="$i"
  done
  fw_changed=1
  echo "Created firewall zone VPN."
fi
has_fwd() {
  for f in $(uci show firewall | sed -n "s/^firewall\.\([^.]*\)=forwarding$/\1/p"); do
    [ "$(uci -q get firewall.$f.src)" = "$1" ] && [ "$(uci -q get firewall.$f.dest)" = "$2" ] && echo "$f"
  done
}
if [ -z "$(has_fwd lan VPN)" ]; then
  f=$(uci add firewall forwarding)
  uci set firewall.$f.src='lan'
  uci set firewall.$f.dest='VPN'
  fw_changed=1
fi
if [ "$KILLSWITCH" = 1 ]; then
  for f in $(has_fwd lan wan); do uci delete firewall.$f; fw_changed=1; echo "Kill switch on: removed LAN -> WAN forwarding."; done
fi
if [ "$fw_changed" = 1 ]; then
  uci commit firewall
  /etc/init.d/firewall reload >/dev/null 2>&1 || true
fi

mkdir -p /www/luci-static/resources/view /usr/share/luci/menu.d /usr/share/rpcd/acl.d
